// Angles use 16.16 turns: zero faces +z; positive turns rotate toward +x.
// The shared sine table avoids platform-dependent trigonometry during replay.

public enum Trig {
    public static let turn: Int64 = 1 << 16
    public static let quarter: Int64 = 1 << 14
    static let tableBits: Int64 = 10
    static let tableSize: Int64 = 1 << 10

    /// Generated by python3 python/whaley.py stadium math --table; shared with the Python reference.
    static let sinQuarter: [Int64] = [
        0, 402, 804, 1206, 1608, 2010, 2412, 2814,
        3216, 3617, 4019, 4420, 4821, 5222, 5623, 6023,
        6424, 6824, 7224, 7623, 8022, 8421, 8820, 9218,
        9616, 10014, 10411, 10808, 11204, 11600, 11996, 12391,
        12785, 13180, 13573, 13966, 14359, 14751, 15143, 15534,
        15924, 16314, 16703, 17091, 17479, 17867, 18253, 18639,
        19024, 19409, 19792, 20175, 20557, 20939, 21320, 21699,
        22078, 22457, 22834, 23210, 23586, 23961, 24335, 24708,
        25080, 25451, 25821, 26190, 26558, 26925, 27291, 27656,
        28020, 28383, 28745, 29106, 29466, 29824, 30182, 30538,
        30893, 31248, 31600, 31952, 32303, 32652, 33000, 33347,
        33692, 34037, 34380, 34721, 35062, 35401, 35738, 36075,
        36410, 36744, 37076, 37407, 37736, 38064, 38391, 38716,
        39040, 39362, 39683, 40002, 40320, 40636, 40951, 41264,
        41576, 41886, 42194, 42501, 42806, 43110, 43412, 43713,
        44011, 44308, 44604, 44898, 45190, 45480, 45769, 46056,
        46341, 46624, 46906, 47186, 47464, 47741, 48015, 48288,
        48559, 48828, 49095, 49361, 49624, 49886, 50146, 50404,
        50660, 50914, 51166, 51417, 51665, 51911, 52156, 52398,
        52639, 52878, 53114, 53349, 53581, 53812, 54040, 54267,
        54491, 54714, 54934, 55152, 55368, 55582, 55794, 56004,
        56212, 56418, 56621, 56823, 57022, 57219, 57414, 57607,
        57798, 57986, 58172, 58356, 58538, 58718, 58896, 59071,
        59244, 59415, 59583, 59750, 59914, 60075, 60235, 60392,
        60547, 60700, 60851, 60999, 61145, 61288, 61429, 61568,
        61705, 61839, 61971, 62101, 62228, 62353, 62476, 62596,
        62714, 62830, 62943, 63054, 63162, 63268, 63372, 63473,
        63572, 63668, 63763, 63854, 63944, 64031, 64115, 64197,
        64277, 64354, 64429, 64501, 64571, 64639, 64704, 64766,
        64827, 64884, 64940, 64993, 65043, 65091, 65137, 65180,
        65220, 65259, 65294, 65328, 65358, 65387, 65413, 65436,
        65457, 65476, 65492, 65505, 65516, 65525, 65531, 65535,
        65536
    ]

    public static func normalize(_ raw: Int64) -> Int64 { floorMod(raw, turn) }

    static func sinAt(_ i: Int64) -> Int64 {
        let q = i >> (tableBits - 2)
        let k = Int(i & (tableSize / 4 - 1))
        switch q {
        case 0: return sinQuarter[k]
        case 1: return sinQuarter[Int(tableSize / 4) - k]
        case 2: return -sinQuarter[k]
        default: return -sinQuarter[Int(tableSize / 4) - k]
        }
    }

    public static func sin(_ turns: Fixed) -> Fixed {
        let n = normalize(turns.raw)
        let shift = Fixed.fractionBits - tableBits
        let i = n >> shift
        let f = n & ((1 << shift) - 1)
        let a = sinAt(i)
        let b = sinAt((i + 1) & (tableSize - 1))
        return Fixed(raw: a + (((b - a) * f) >> shift))
    }

    public static func cos(_ turns: Fixed) -> Fixed { sin(Fixed(raw: turns.raw + quarter)) }

    public static func forward(_ heading: Fixed) -> Vec3 { Vec3(sin(heading), .zero, cos(heading)) }

    public static func right(_ heading: Fixed) -> Vec3 { Vec3(cos(heading), .zero, -sin(heading)) }

    public static func direction(yaw: Fixed, pitch: Fixed) -> Vec3 {
        let cp = cos(pitch)
        return Vec3(cp * sin(yaw), sin(pitch), cp * cos(yaw))
    }

    public static func up(yaw: Fixed, pitch: Fixed) -> Vec3 {
        let sp = sin(pitch), cp = cos(pitch)
        return Vec3(-(sp * sin(yaw)), cp, -(sp * cos(yaw)))
    }

    /// Bisect the first quadrant for nonnegative ax and az, using the shared sine table.
    static func firstQuadrantAngle(_ ax: Fixed, _ az: Fixed) -> Int64 {
        var lo: Int64 = 0, hi: Int64 = quarter
        while lo < hi {
            let mid = (lo + hi) >> 1
            if sin(Fixed(raw: mid)) * az - cos(Fixed(raw: mid)) * ax < .zero { lo = mid + 1 } else { hi = mid }
        }
        return lo
    }

    public static func bearing(dx: Fixed, dz: Fixed) -> Fixed {
        if dx == .zero && dz == .zero { return .zero }
        let a = firstQuadrantAngle(dx.magnitude, dz.magnitude)
        if dx >= .zero && dz >= .zero { return Fixed(raw: a) }
        if dz < .zero { return Fixed(raw: dx >= .zero ? 2 * quarter - a : 2 * quarter + a) }
        return Fixed(raw: normalize(turn - a))
    }

    public static func elevation(dy: Fixed, horizontal: Fixed) -> Fixed {
        let a = firstQuadrantAngle(dy.magnitude, horizontal)
        return Fixed(raw: dy >= .zero ? a : -a)
    }
}
